#{{ ansible_managed }}
{% if ansible_facts['os_family'] == 'RedHat' %} 
user              nginx;
{% endif %}
{% if ansible_facts['os_family'] == 'Debian' %} 
user              www-data;
{% endif %}

worker_processes  {{ ansible_facts['processor_count'] }};
pid        /var/run/nginx.pid;


events {
    worker_connections  {{ nginx_max_clients }};
}


http {
        ssl_protocols TLSv1.2 TLSv1.3;
        include /etc/nginx/mime.types;
        default_type application/octet-stream;

        access_log {{ nginx_log_dir}}/{{ nginx_access_log_name}};
        error_log {{ nginx_log_dir}}/{{ nginx_error_log_name}};

{% for k,v in nginx_http_params.items() %}
        {{ k }}  {{ v }};
{% endfor %}

        gzip on;
        gzip_disable "msie6";

        include /etc/nginx/conf.d/*.conf;
        include /etc/nginx/sites-enabled/*;
}

server {

{% if nginx_separate_logs_per_site == True %}
	access_log {{ nginx_log_dir}}/{{ item.server.server_name}}-{{ nginx_access_log_name}};
	error_log {{ nginx_log_dir}}/{{ item.server.server_name}}-{{ nginx_error_log_name}};
{% endif %}

{% for k,v in item.server.items() %}
{% if 'location' not in k and k != 'file_name' %}
{{ k }} {{ v }};
{% endif %}
{% endfor %} 

{% for k,v in item.server.items() if 'location' in k %}
  location {{ v.name }} {
{% for x,y in v.items() if x != 'name' %} 
      {{ x }} {{ y }};
{% endfor %}
  }
{% endfor %}
}

